 break of either edge would shift the phase from channel toward range and lower the Always-In relevance from medium toward low."], "window_bars": 120}, "freshness": "stale"}}, "raw": {"H1": [{"close": "2405.67", "close_time_ms": 1789563599999, "high": "2421.71", "low": "2402.32", "open": "2421.43", "open_time_ms": 1789560000000, "volume": "2315163.628"}, {"close": "2393.1", "close_time_ms": 1789567199999, "high": "2405.74", "low": "2391.94", "open": "2405.65", "open_time_ms": 1789563600000, "volume": "2323332.147"}, {"close": "2387.35", "close_time_ms": 1789570799999, "high": "2396.73", "low": "2384.32", "open": "2393.1", "open_time_ms": 1789567200000, "volume": "2344754.302"}, {"close": "2392.87", "close_time_ms": 1789574399999, "high": "2397.84", "low": "2384.29", "open": "2387.35", "open_time_ms": 1789570800000, "volume": "2561435.692"}, {"close": "2391.1", "close_time_ms": 1789577999999, "high": "2395.87", "low": "2386.73", "open": "2392.87", "open_time_ms": 1789574400000, "volume": "1973346.781"}, {"close": "2384.88", "close_time_ms": 1789581599999, "high": "2392.25", "low": "2370.54", "open": "2391.1", "open_time_ms": 1789578000000, "volume": "2783910.164"}, {"close": "2394.67", "close_time_ms": 1789585199999, "high": "2419.22", "low": "2377.61", "open": "2384.88", "open_time_ms": 1789581600000, "volume": "3152893.004"}, {"close": "2407.99", "close_time_ms": 1789588799999, "high": "2412.49", "low": "2378.84", "open": "2391.89", "open_time_ms": 1789585200000, "volume": "2055736.612"}, {"close": "2410.09", "close_time_ms": 1789592399999, "high": "2416.72", "low": "2404.55", "open": "2407.91", "open_time_ms": 1789588800000, "volume": "2360830.123"}, {"close": "2404.17", "close_time_ms": 1789595999999, "high": "2411.77", "low": "2400.28", "open": "2410.13", "open_time_ms": 1789592400000, "volume": "1949272.699"}, {"close": "2392.19", "close_time_ms": 1789599599999, "high": "2404.61", "low": "2389.13", "open": "2404.18", "open_time_ms": 1789596000000, "volume": "20